import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sourceRoot = path.join(root, "apps/electrophysiology-lab/src");
const outputPath = path.join(sourceRoot, "app.bundle.js");

// The source remains split into testable ES modules. This deterministic build
// creates a classic-script copy so the laboratory also works from file://.
const modules = [
  {
    name: "signalModule",
    file: "core/signal.js",
    exports: ["median", "medianAbsoluteDeviation", "analyzeTrace", "createDemoTrace"],
  },
  {
    name: "fieldPotentialModule",
    file: "core/fieldPotential.js",
    prelude: "const { median, medianAbsoluteDeviation } = signalModule;",
    exports: [
      "LEGACY_POPS_PROFILE",
      "PAIRED_POPS_PROFILE",
      "smoothSavitzkyGolay11x3",
      "detectLegacyArtifacts",
      "detectPairedLegacyArtifacts",
      "measurePopulationSpikes",
    ],
  },
  {
    name: "inferenceModule",
    file: "core/inference.js",
    exports: ["guessTimeUnit", "suggestWorkbookAnalysis", "isImplausibleTimeScale", "signalColumnChoices"],
  },
  {
    name: "reviewModule",
    file: "core/review.js",
    exports: [
      "REVIEW_SCHEMA",
      "buildReviewSessionKey",
      "buildTraceReviewKey",
      "emptyReviewState",
      "loadReviewState",
      "storeReviewRecord",
      "isReviewCurrent",
      "reviewDecisionFromShortcut",
    ],
  },
  {
    name: "correctionsModule",
    file: "core/corrections.js",
    prelude: "const { median, medianAbsoluteDeviation } = signalModule;",
    exports: [
      "CORRECTION_POINT_NAMES",
      "appendCorrectionAudit",
      "setPointCorrection",
      "removePointCorrection",
      "applyPointCorrections",
    ],
  },
  {
    name: "workbookModule",
    file: "io/workbook.js",
    exports: [
      "loadSheetJs",
      "parseWorkbook",
      "columnValues",
      "buildTraceExportBaseName",
      "exportAnalysisWorkbook",
    ],
  },
  {
    name: "plotModule",
    file: "ui/plot.js",
    exports: ["SignalPlot"],
  },
];

function removeModuleSyntax(source) {
  return source
    .replace(/^import\b[\s\S]*?;\s*/gm, "")
    .replace(/^export\s+/gm, "");
}

function indent(source, spaces = 2) {
  const padding = " ".repeat(spaces);
  return source.split("\n").map((line) => `${padding}${line}`).join("\n");
}

const sections = [
  "/* Generated by scripts/build-ephys-bundle.mjs. Edit src modules, not this file. */",
  "(() => {",
  "  \"use strict\";",
];

for (const moduleDefinition of modules) {
  const source = removeModuleSyntax(await readFile(path.join(sourceRoot, moduleDefinition.file), "utf8")).trim();
  sections.push(`  const ${moduleDefinition.name} = (() => {`);
  if (moduleDefinition.prelude) sections.push(`    ${moduleDefinition.prelude}`);
  sections.push(indent(source, 4));
  sections.push(`    return { ${moduleDefinition.exports.join(", ")} };`);
  sections.push("  })();");
}

const appSource = removeModuleSyntax(await readFile(path.join(sourceRoot, "app.js"), "utf8")).trim();
sections.push("  (() => {");
sections.push("    const { analyzeTrace, createDemoTrace } = signalModule;");
sections.push("    const { LEGACY_POPS_PROFILE, PAIRED_POPS_PROFILE, measurePopulationSpikes } = fieldPotentialModule;");
sections.push("    const { guessTimeUnit, isImplausibleTimeScale, signalColumnChoices, suggestWorkbookAnalysis } = inferenceModule;");
sections.push("    const { buildTraceExportBaseName, columnValues, exportAnalysisWorkbook, parseWorkbook } = workbookModule;");
sections.push("    const { buildReviewSessionKey, buildTraceReviewKey, emptyReviewState, isReviewCurrent, loadReviewState, reviewDecisionFromShortcut, storeReviewRecord } = reviewModule;");
sections.push("    const { appendCorrectionAudit, applyPointCorrections, removePointCorrection, setPointCorrection } = correctionsModule;");
sections.push("    const { SignalPlot } = plotModule;");
sections.push(indent(appSource, 4));
sections.push("  })();");
sections.push("})();", "");

const bundle = sections.join("\n");
if (process.argv.includes("--check")) {
  const currentBundle = await readFile(outputPath, "utf8").catch(() => "");
  if (currentBundle !== bundle) {
    throw new Error("app.bundle.js está desactualizado; ejecuta node scripts/build-ephys-bundle.mjs");
  }
} else {
  await writeFile(outputPath, bundle, "utf8");
}
